<?php
if(PHP_SAPI!=='cli')exit;
require dirname(__DIR__,2).'/wp-load.php';$p=json_decode(file_get_contents(__DIR__.'/replacement-plan.json'),true);$errors=[];$urls=[];
foreach($p['new'] as $slug=>$id){$file=get_attached_file($id);if(!file_exists($file))$errors[]='Missing '.$slug;$urls[]=wp_get_attachment_url($id);if(!str_starts_with($slug,'scene-')){[$w,$h]=getimagesize($file);if($w!==1600||$h!==1600)$errors[]='Dimensions '.$slug;}}
$ids=json_decode(file_get_contents(dirname(__DIR__).'/catalog-refresh/product-ids.json'),true);$variants=0;foreach($ids as $slug=>$id){if(get_post_thumbnail_id($id)!==$p['new'][$slug])$errors[]='Wrong product image '.$slug;$variants+=count(get_post_meta($id,'_catalog_variants',true));}
foreach(get_posts(['post_type'=>['post','page','elementor_library'],'post_status'=>'any','numberposts'=>-1]) as $post){$text=$post->post_content.' '.get_post_meta($post->ID,'_elementor_data',true).' '.wp_json_encode(get_post_meta($post->ID,'_elementor_page_settings',true));foreach($p['urls'] as $old=>$new)if(str_contains($text,$old)||str_contains($text,str_replace('/','\\/',$old)))$errors[]='Old URL on '.$post->ID.': '.$old;if(in_array(get_post_thumbnail_id($post->ID),$p['retire'],true))$errors[]='Old thumbnail '.$post->ID;}
file_put_contents(__DIR__.'/image-urls.json',json_encode($urls));file_put_contents(__DIR__.'/audit-report.json',json_encode(['assets'=>count($p['new']),'products'=>count($ids),'variants'=>$variants,'obsolete_media'=>count($p['retire']),'errors'=>$errors],JSON_PRETTY_PRINT));if($errors)throw new Exception(implode("\n",$errors));echo count($p['new']).' images, '.count($ids).' product assignments and '.$variants." variants verified; no old active image references.\n";
